const VIEW = { lockup: '-164.4 -6 1930.4 1186', badge: '-164.4 -6 1930.4 1012' }
const VH = { lockup: 1.186, badge: 1.012 }
const VW = 1.9304

export default function PitBoardLogo({
  height = 34,
  variant = 'lockup',
  sheen = true,
  style,
  ...rest
}) {
  const uid = useId().replace(/:/g, "")
  const mono = variant === 'mono'
  const key = variant === 'lockup' ? 'lockup' : 'badge'
  const chrome = mono ? "#FFFFFF" : "url(#chrome" + uid + ")"

  const bars = []
  ROWS.forEach((y, r) => COLORS.forEach(([a, b], i) => {
    const x = PAD + i * (CW + GAP)
    bars.push(
      <rect key={"a" + r + i} x={x} y={y} width={CW * SPLIT} height={BAR} fill={mono ? "#FFFFFF" : a} />,
      <rect key={"b" + r + i} x={x + CW * SPLIT} y={y} width={CW * (1 - SPLIT)} height={BAR} fill={mono ? "#FFFFFF" : b} opacity={mono ? 0.45 : 1} />
    )
  }))

  const css =
    "@keyframes pbSheen" + uid + "{0%{opacity:0;transform:translateX(-700px)}12%{opacity:.85}88%{opacity:.85}100%{opacity:0;transform:translateX(2100px)}}" +
    "#pb" + uid + " .pbSheen{opacity:0}" +
    "#pb" + uid + ":hover .pbSheen{animation:pbSheen" + uid + " .85s ease-in-out}"

  return (
    <svg
      id={"pb" + uid}
      xmlns="http://www.w3.org/2000/svg"
      viewBox={VIEW[key]}
      width={Math.round(height * VW)}
      height={Math.round(height * VH[key])}
      role="img"
      aria-label={variant === "lockup" ? "PitBoard Analytics" : "PitBoard"}
      style={{ display: "block", color: "#F4F4F2", ...style }}
      {...rest}
    >
      {sheen && !mono && <style dangerouslySetInnerHTML={{ __html: css }} />}
      <defs>
        <clipPath id={"plate" + uid}>
          <rect x="0" y="0" width="1760" height="1000" rx="80" ry="80" />
        </clipPath>
        <clipPath id={"word" + uid}>
          <path d={WORD} />
        </clipPath>
        {!mono && (
          <linearGradient id={"chrome" + uid} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#FFFFFF" />
            <stop offset="0.38" stopColor="#F4F4F4" />
            <stop offset="0.52" stopColor="#8F9195" />
            <stop offset="0.60" stopColor="#E6E7EA" />
            <stop offset="0.82" stopColor="#FFFFFF" />
            <stop offset="1" stopColor="#B9BBC0" />
          </linearGradient>
        )}
        <linearGradient id={"sheen" + uid} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#FFFFFF" stopOpacity="0" />
          <stop offset="0.5" stopColor="#FFFFFF" />
          <stop offset="1" stopColor="#FFFFFF" stopOpacity="0" />
        </linearGradient>
      </defs>

      <g transform="skewX(-9)">
        <rect x="0" y="0" width="1760" height="1000" rx="80" ry="80" fill={mono ? "#000000" : "#08090A"} />
        <g clipPath={"url(#plate" + uid + ")"}>{bars}</g>
        <path d={WORD} fill={chrome} />
        {sheen && !mono && (
          <g clipPath={"url(#word" + uid + ")"}>
            <rect className="pbSheen" x="-200" y="300" width="260" height="400" fill={"url(#sheen" + uid + ")"} />
          </g>
        )}
      </g>

      {variant === "lockup" && (
        <g transform="translate(-79.2 0) translate(0 1118) skewX(-9) translate(0 -1118)">
          <path d={TAG} fill="currentColor" />
        </g>
      )}
    </svg>
  )
}
